'use strict';
document.getElementById('contactform').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),button=document.getElementById('contactsubmit'),status=document.getElementById('contactstatus');button.disabled=true;status.textContent='접수 중입니다.';try{if(form.get('website'))throw Error('입력 내용을 확인해 주세요.');if(form.get('consent')!=='on')throw Error('문의 처리를 위한 개인정보 수집에 동의해 주세요.');const configResponse=await fetch('/api/config',{signal:AbortSignal.timeout(10000)}),config=await configResponse.json();if(!config.communityReady)throw Error('현재 문의 서버에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.');const response=await fetch(config.supabaseUrl+'/rest/v1/rpc/submit_support',{method:'POST',headers:{apikey:config.supabaseKey,'Content-Type':'application/json'},body:JSON.stringify({p_email:form.get('email'),p_subject:form.get('subject'),p_body:form.get('body')}),signal:AbortSignal.timeout(12000)});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(/5분/.test(data.message||'')?'동일 이메일 문의는 5분 뒤 다시 접수할 수 있어요.':'문의가 저장되지 않았습니다. 잠시 후 다시 시도해 주세요.');}status.textContent='문의가 저장되었습니다. 운영자가 내용을 확인합니다.';event.target.reset();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
